    if SH > 0:
        predictive_block = (RI + 1) * (SH - 1) / (SH + 1)
    else:
        predictive_block = 0.0

    # Estimate retrieval urgency based on AVG and CUR
    if AVG > 0 and CUR > 0:
        urgency_ratio = (AVG / CUR) * (1 / (SH + 1))
